/* Basque Names Database — name-meaning lookup demo (jahdb-demo-1.0)
 * RUN ON PC: save as demo.js, then run:  node demo.js [name]
 * RUN IN BROWSER: paste into the console and press Enter. */
var TABLE = {"Aitor": "The legendary patriarch of the Basques.", "Maite": "beloved — Basque", "Inigo": "my little love — Basque ene (mine) + -ko", "Ane": "grace — Hebrew Hannah, via Basque", "Koldo": "A traditional Basque masculine name.", "Edurne": "snow — Basque elur", "Echeverria": "The classic Basque house-name surname.", "Zubizarreta": "A classic place-based surname.", "Mendizabal": "A classic place-based surname.", "Aguirre": "A widespread Basque surname."};
function lookup(q){
  q=String(q||'').toLowerCase().trim();
  var keys=Object.keys(TABLE);
  for(var i=0;i<keys.length;i++){ if(keys[i].toLowerCase()===q) return keys[i]+' — '+TABLE[keys[i]]; }
  var hits=keys.filter(function(k){return k.toLowerCase().indexOf(q)>=0;});
  if(!hits.length) return 'No match for "'+q+'". Try: '+keys.slice(0,5).join(', ');
  return hits.map(function(k){return k+' — '+TABLE[k];}).join('\n');
}
var q=(typeof process!=='undefined'&&process.argv[2])||'Aitor';
console.log(lookup(q));

